namespace UniversityCourseCatalog.Models;

public class Department
{
    public string Id { get; set; } = "";
    public string Name { get; set; } = "";
    public string Description { get; set; } = "";
}

namespace UniversityCourseCatalog.Models;

public class Instructor
{
    public string Name { get; set; } = "";
    public string Title { get; set; } = "";
    public string Bio { get; set; } = "";
    public string Email { get; set; } = "";
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public string Id { get; set; } = "";
    public string Title { get; set; } = "";
    public string DepartmentId { get; set; } = "";
    public string DepartmentName { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string Level { get; set; } = "";
    public bool IsFeatured { get; set; }
    public Instructor Instructor { get; set; } = new();
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100, ErrorMessage = "Name cannot exceed 100 characters.")]
    public string StudentName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]+$", ErrorMessage = "Student ID must contain only letters and numbers.")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    public string CourseId { get; set; } = "";
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CourseCatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CourseCatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and software systems." },
            new() { Id = "MATH", Name = "Mathematics", Description = "Exploration of numbers, structures, and mathematical reasoning." },
            new() { Id = "PHYS", Name = "Physics", Description = "Understanding the fundamental laws of the universe." },
            new() { Id = "BIO", Name = "Biology", Description = "Study of living organisms and life processes." },
            new() { Id = "ENG", Name = "English", Description = "Literature, writing, and language studies." },
            new() { Id = "HIST", Name = "History", Description = "Examination of past events and civilizations." }
        };

        _courses = new List<Course>
        {
            new()
            {
                Id = "CS101", Title = "Introduction to Programming", DepartmentId = "CS", DepartmentName = "Computer Science",
                Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented principles.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00-9:50 AM", Level = "Undergraduate", IsFeatured = true,
                Instructor = new() { Name = "Dr. Ada Lovelace", Title = "Professor", Bio = "Expert in programming languages and software engineering with 15 years of teaching experience.", Email = "alovelace@university.edu" }
            },
            new()
            {
                Id = "CS201", Title = "Data Structures and Algorithms", DepartmentId = "CS", DepartmentName = "Computer Science",
                Description = "Study of fundamental data structures including arrays, linked lists, trees, and graphs, along with algorithm design and analysis.",
                Credits = 4, Schedule = "Tue/Thu 10:00-11:15 AM", Level = "Undergraduate", IsFeatured = false,
                Instructor = new() { Name = "Dr. Alan Turing", Title = "Associate Professor", Bio = "Specializes in algorithm design and computational complexity.", Email = "aturing@university.edu" }
            },
            new()
            {
                Id = "CS501", Title = "Machine Learning", DepartmentId = "CS", DepartmentName = "Computer Science",
                Description = "Introduction to machine learning concepts including supervised learning, unsupervised learning, and neural networks.",
                Credits = 3, Schedule = "Mon/Wed 2:00-3:15 PM", Level = "Graduate", IsFeatured = true,
                Instructor = new() { Name = "Dr. Grace Hopper", Title = "Professor", Bio = "Pioneer in machine learning research with numerous publications.", Email = "ghopper@university.edu" }
            },
            new()
            {
                Id = "MATH101", Title = "Calculus I", DepartmentId = "MATH", DepartmentName = "Mathematics",
                Description = "Introduction to differential and integral calculus. Covers limits, derivatives, and integrals of single-variable functions.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00-10:50 AM", Level = "Undergraduate", IsFeatured = false,
                Instructor = new() { Name = "Dr. Euler Gauss", Title = "Professor", Bio = "Award-winning mathematician with a passion for teaching calculus.", Email = "egauss@university.edu" }
            },
            new()
            {
                Id = "MATH301", Title = "Linear Algebra", DepartmentId = "MATH", DepartmentName = "Mathematics",
                Description = "Study of vector spaces, linear transformations, matrices, and systems of linear equations.",
                Credits = 3, Schedule = "Tue/Thu 1:00-2:15 PM", Level = "Undergraduate", IsFeatured = false,
                Instructor = new() { Name = "Dr. Emmy Noether", Title = "Associate Professor", Bio = "Researcher in abstract algebra and theoretical physics.", Email = "enoether@university.edu" }
            },
            new()
            {
                Id = "PHYS101", Title = "General Physics I", DepartmentId = "PHYS", DepartmentName = "Physics",
                Description = "Mechanics, thermodynamics, and waves. Includes laboratory sessions for hands-on experimentation.",
                Credits = 4, Schedule = "Mon/Wed/Fri 11:00-11:50 AM", Level = "Undergraduate", IsFeatured = true,
                Instructor = new() { Name = "Dr. Richard Feynman", Title = "Professor", Bio = "Renowned physicist and exceptional educator known for clear explanations.", Email = "rfeynman@university.edu" }
            },
            new()
            {
                Id = "PHYS502", Title = "Quantum Mechanics", DepartmentId = "PHYS", DepartmentName = "Physics",
                Description = "Advanced study of quantum theory including wave functions, operators, and quantum entanglement.",
                Credits = 3, Schedule = "Tue/Thu 3:00-4:15 PM", Level = "Graduate", IsFeatured = false,
                Instructor = new() { Name = "Dr. Niels Bohr", Title = "Professor", Bio = "Leading researcher in quantum physics and atomic structure.", Email = "nbohr@university.edu" }
            },
            new()
            {
                Id = "BIO101", Title = "Introduction to Biology", DepartmentId = "BIO", DepartmentName = "Biology",
                Description = "Survey of biological principles including cell biology, genetics, evolution, and ecology.",
                Credits = 4, Schedule = "Mon/Wed/Fri 1:00-1:50 PM", Level = "Undergraduate", IsFeatured = false,
                Instructor = new() { Name = "Dr. Charles Darwin", Title = "Professor", Bio = "Evolutionary biologist with extensive field research experience.", Email = "cdarwin@university.edu" }
            },
            new()
            {
                Id = "BIO305", Title = "Molecular Biology", DepartmentId = "BIO", DepartmentName = "Biology",
                Description = "Study of biological processes at the molecular level, including DNA replication, transcription, and translation.",
                Credits = 3, Schedule = "Tue/Thu 9:00-10:15 AM", Level = "Undergraduate", IsFeatured = false,
                Instructor = new() { Name = "Dr. Rosalind Franklin", Title = "Associate Professor", Bio = "Expert in molecular biology and X-ray crystallography.", Email = "rfranklin@university.edu" }
            },
            new()
            {
                Id = "ENG101", Title = "English Composition", DepartmentId = "ENG", DepartmentName = "English",
                Description = "Develop critical writing skills through essays, research papers, and creative writing exercises.",
                Credits = 3, Schedule = "Mon/Wed 10:00-11:15 AM", Level = "Undergraduate", IsFeatured = false,
                Instructor = new() { Name = "Dr. Jane Austen", Title = "Professor", Bio = "Published author and writing instructor with decades of experience.", Email = "jausten@university.edu" }
            },
            new()
            {
                Id = "ENG420", Title = "American Literature", DepartmentId = "ENG", DepartmentName = "English",
                Description = "Survey of American literary works from the colonial period to the present, examining major authors and movements.",
                Credits = 3, Schedule = "Tue/Thu 11:00 AM-12:15 PM", Level = "Undergraduate", IsFeatured = false,
                Instructor = new() { Name = "Dr. Mark Twain", Title = "Associate Professor", Bio = "Specialist in American literature and cultural studies.", Email = "mtwain@university.edu" }
            },
            new()
            {
                Id = "HIST101", Title = "World History I", DepartmentId = "HIST", DepartmentName = "History",
                Description = "Survey of world history from ancient civilizations to the early modern period.",
                Credits = 3, Schedule = "Mon/Wed/Fri 2:00-2:50 PM", Level = "Undergraduate", IsFeatured = true,
                Instructor = new() { Name = "Dr. Howard Zinn", Title = "Professor", Bio = "Historian specializing in social movements and global history.", Email = "hzinn@university.edu" }
            },
            new()
            {
                Id = "HIST510", Title = "Historiography", DepartmentId = "HIST", DepartmentName = "History",
                Description = "Study of historical methods, interpretation, and the philosophy of history.",
                Credits = 3, Schedule = "Thu 6:00-8:45 PM", Level = "Graduate", IsFeatured = false,
                Instructor = new() { Name = "Dr. Herodotus Smith", Title = "Professor", Bio = "Expert in historiographical methods and ancient history.", Email = "hsmith@university.edu" }
            },
            new()
            {
                Id = "MATH510", Title = "Real Analysis", DepartmentId = "MATH", DepartmentName = "Mathematics",
                Description = "Rigorous treatment of real number theory, sequences, series, continuity, and differentiability.",
                Credits = 3, Schedule = "Mon/Wed 4:00-5:15 PM", Level = "Graduate", IsFeatured = false,
                Instructor = new() { Name = "Dr. Bernhard Riemann", Title = "Professor", Bio = "Specialist in analysis and differential geometry.", Email = "briemann@university.edu" }
            }
        };
    }

    public IReadOnlyList<Department> GetDepartments() => _departments.AsReadOnly();

    public IReadOnlyList<Course> GetCourses(string? searchTerm, string? departmentId, string? level)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(departmentId))
        {
            query = query.Where(c => c.DepartmentId.Equals(departmentId, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(level))
        {
            query = query.Where(c => c.Level.Equals(level, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList().AsReadOnly();
    }

    public Course? GetCourseById(string id) =>
        _courses.FirstOrDefault(c => c.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList().AsReadOnly();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request) => true;
}

