@page "/enroll"
@inject CourseCatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Enrollment Request Submitted!</h4>
        <p>Your enrollment request has been received with the following details:</p>
        <ul>
            <li><strong>Student Name:</strong> @Request!.StudentName</li>
            <li><strong>Student ID:</strong> @Request!.StudentId</li>
            <li><strong>Course:</strong> @Request!.CourseId</li>
        </ul>
        <hr />
        <a href="courses" class="btn btn-primary">Back to Catalog</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-8">
            <div class="card">
                <div class="card-body">
                    <EditForm Model="Request" method="post" OnValidSubmit="HandleSubmit" FormName="enrollment">
                        <AntiforgeryToken />
                        <DataAnnotationsValidator />

                        <div class="mb-3">
                            <label for="studentName" class="form-label">Student Name</label>
                            <InputText id="studentName" class="form-control" @bind-Value="Request!.StudentName" />
                            <ValidationMessage For="() => Request!.StudentName" />
                        </div>

                        <div class="mb-3">
                            <label for="studentId" class="form-label">Student ID</label>
                            <InputText id="studentId" class="form-control" @bind-Value="Request!.StudentId" />
                            <ValidationMessage For="() => Request!.StudentId" />
                        </div>

                        <div class="mb-3">
                            <label for="courseId" class="form-label">Course</label>
                            <InputSelect id="courseId" class="form-select" @bind-Value="Request!.CourseId">
                                <option value="">-- Select a Course --</option>
                                @foreach (var course in courses)
                                {
                                    <option value="@course.Id">@course.Id - @course.Title</option>
                                }
                            </InputSelect>
                            <ValidationMessage For="() => Request!.CourseId" />
                        </div>

                        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                    </EditForm>
                </div>
            </div>

            <div class="mt-3">
                <a href="courses">Back to Catalog</a>
            </div>
        </div>
    </div>
}

@code {
    [SupplyParameterFromQuery]
    public string? CourseId { get; set; }

    [SupplyParameterFromForm]
    public EnrollmentRequest? Request { get; set; }

    private IReadOnlyList<Course> courses = [];
    private bool submitted;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetCourses(null, null, null);
        Request ??= new EnrollmentRequest
        {
            CourseId = CourseId ?? ""
        };
    }

    private void HandleSubmit()
    {
        CatalogService.SubmitEnrollmentRequest(Request!);
        submitted = true;
    }
}

